    for r in range(rows):
        walls = [c for c in range(cols) if grid[r][c] == 8]

        if len(walls) >= 1:
            left_wall = walls[0]
            right_wall = walls[-1]

            # Fill between walls
            for c in range(left_wall + 1, right_wall):
